import json
import numpy as np,pandas as pd
from request_value import BASE
from update_calibration_experiment import hierarchical

def main():
 out=BASE/'results/candidate_complementarity';out.mkdir(exist_ok=True);a=pd.read_csv(BASE/'results/distance_aligned_return/windows.csv.gz');b=pd.read_csv(BASE/'results/causal_decay_selector/windows.csv.gz');keys=['window_id','dataset','environment_id','episode_uuid','side'];base=a[a.method=='secant'][keys+['nade']].rename(columns={'nade':'baseline'});distance=a[a.method=='distance_return'][['window_id','nade']].rename(columns={'nade':'distance'});selector=b[b.method=='causal_selector'][['window_id','nade']].rename(columns={'nade':'selector'});z=base.merge(distance,on='window_id',validate='one_to_one').merge(selector,on='window_id',validate='one_to_one');assert len(z)==1527;z['distance_gain']=z.baseline-z.distance;z['selector_gain']=z.baseline-z.selector;z['oracle']=z[['distance','selector']].min(axis=1);z['both_improve']=(z.distance_gain>0)&(z.selector_gain>0);z['only_distance']=(z.distance_gain>0)&(z.selector_gain<=0);z['only_selector']=(z.distance_gain<=0)&(z.selector_gain>0);z['neither']=(z.distance_gain<=0)&(z.selector_gain<=0);z.to_csv(out/'windows.csv',index=False);summary=hierarchical(z,[],['baseline','distance','selector','oracle']);summary.to_csv(out/'summary.csv',index=False)
 # Pointwise hindsight oracle uses shared error rows, never reference-derived strategy inputs.
 pa=pd.read_csv(BASE/'results/distance_nested_calibration/outer_points.csv.gz').query("model=='distance_return' and calibration=='pooled'");pb=pd.read_csv(BASE/'results/selector_matched_calibration/outer_points.csv.gz');pairs=pa[keys+['index','error']].merge(pb[['window_id','index','error']],on=['window_id','index'],suffixes=('_distance','_selector'),validate='one_to_one');pairs['oracle_error']=pairs[['error_distance','error_selector']].min(axis=1);assert len(pairs)==47037
 audit=dict(windows=len(z),shared_points=len(pairs),raw_window_outcomes={k:int(z[k].sum()) for k in ['both_improve','only_distance','only_selector','neither']},raw_gain_correlation=float(z[['distance_gain','selector_gain']].corr().iloc[0,1]),window_oracle_gain_pct=float(100*(1-summary.oracle.iloc[0]/summary.baseline.iloc[0])),oracle_not_deployable=True,scope='posthoc complementarity diagnosis, not proof a causal selector or blend will improve');(out/'audit.json').write_text(json.dumps(audit,indent=2),encoding='utf8');print(summary.to_string(index=False));print(json.dumps(audit))
if __name__=='__main__':main()
